+    /// Incrementing the generation also restarts a presented screen's load.
+    func accountChanged() {
+        latestAttempt += 1
+        isFetching = false
+        state = .signedOut
+        lastRefreshError = nil
+        attemptedLoad = false
+        accountGeneration += 1
