import HuggingFaceAuth
import ReachyDesign
import ReachyKit
import SwiftUI

/// The sheets the whole interface shares, mounted once above both the gate and the
/// shell so that connecting — which throws the tree below it away — does not
/// dismiss one mid-flight.
///
/// **Nothing stateful may be constructed in a sheet's content closure.** SwiftUI
/// re-runs that closure on every update of the view the sheet hangs off, which
/// here means every `RobotSession.phase` change — and the candidate sweep produces
/// one every 10 s while the gate is up. Whatever a model was holding is thrown
/// away with it, and a `.task` that filled it does not run a second time. Both
/// models below are therefore handed in already built: `remoteRobots` by the root,
/// `HFSignInModel` by `HFAccountSection`, which adopts the first one it is given
/// into `@State` and ignores every replacement.
struct RootSheets: ViewModifier {
    let session: RobotSession
    let hfAccount: HFAccount
    let remoteRobots: YourReachiesModel
    let router: ReachyRouter
    let connect: (CentralRobot) -> Void

    func body(content: Content) -> some View {
        @Bindable var router = router
        return content
            .sheet(isPresented: $router.showsAccount) {
                NavigationStack {
                    HFSignInScreen(session: session, model: HFSignInModel(account: hfAccount))
                        .toolbar {
                            ToolbarItem(placement: .cancellationAction) {
                                Button(.reachy("Done")) { router.showsAccount = false }
                            }
                        }
                }
            }
            .sheet(isPresented: $router.showsRemoteRobots) {
                NavigationStack {
                    YourReachiesScreen(
                        model: remoteRobots,
                        connect: connect,
                        // Pushed inside this sheet rather than sending the user to
                        // the robot's Settings tab: that tab does not exist until a
                        // robot is connected — exactly the case that brings anyone
                        // here.
                        signIn: { HFSignInScreen(session: session, model: HFSignInModel(account: hfAccount)) }
                    )
                }
            }
            .sheet(isPresented: $router.showsPermissions) {
                NavigationStack {
                    // Only a LAN session proves the local network was granted; a relay
                    // session proves the opposite is possible, which is half the reason
                    // this screen is reachable from the gate at all.
                    PermissionsScreen(localNetworkProvenByConnection: isConnectedOverLAN)
                        .toolbar {
                            ToolbarItem(placement: .cancellationAction) {
                                Button(.reachy("Done")) { router.showsPermissions = false }
                            }
                        }
                }
            }
    }

    private var isConnectedOverLAN: Bool {
        switch session.link {
        case .lan: true
        // A relay session proves nothing about the local network, and `.none` proves
        // less — which is the case this sheet is reachable from the gate for.
        case .none, .remote: false
        }
    }
}

import ReachyDesign
import ReachyKit
import SwiftUI

/// The three ways to reach a robot, one segment each, under a rail that says how
/// the current attempt is going.
///
/// Two things stay out of the segments on purpose, and both are load-bearing:
///
/// - **Bluetooth setup**, because a robot that has never been on a network is
///   exactly the one keeping the sweep failing, and burying the way out behind a
///   segment the reader has no reason to open would be the wrong place for it.
/// - **`disabled` is applied section by section**, never to the form. It is
///   cumulative and a child cannot re-enable itself, so one modifier on the form
///   would take the Bluetooth button down with everything else — and the sweep it
///   waits on runs every 10 s forever when nothing answers.
struct ConnectionScreen: View {
    let session: RobotSession
    let progress: ConnectProgressModel
    /// Absent in previews and wherever the remote list has nowhere to be presented
    /// from, which is what hides that segment's content rather than a flag.
    var showRemoteRobots: (() -> Void)?
    /// Opens the privacy screen. Optional for the same reason as the list above —
    /// the sheet belongs to the root, and a leaf that reached for the router
    /// directly could not be previewed.
    var showPermissions: (() -> Void)?

    @State private var browser: RobotBrowser
    @State private var manualInput: String
    @State private var route: ConnectRoute
    @Environment(\.reachyPreviewMode) private var previewMode
    @State private var resolving: String?
    @State private var showsOnboarding = false
    @State private var awaitedHardwareID = KnownRobots.pendingProvisionedHardwareID
    /// Resolved in `onAppear` rather than defaulted here: a default argument is
    /// evaluated in a nonisolated context, and both models are main-actor isolated.
    @State private var knownRobots: KnownRobotsModel?
    @State private var sweep: CandidateSweep?

    init(
        session: RobotSession,
        progress: ConnectProgressModel,
        browser: RobotBrowser = RobotBrowser(),
        manualInput: String? = nil,
        knownRobots: KnownRobotsModel? = nil,
        sweep: CandidateSweep? = nil,
        route: ConnectRoute = .network,
        showRemoteRobots: (() -> Void)? = nil,
        showPermissions: (() -> Void)? = nil
    ) {
        self.session = session
        self.progress = progress
        self.showRemoteRobots = showRemoteRobots
        self.showPermissions = showPermissions
        _browser = State(initialValue: browser)
        _manualInput = State(initialValue: manualInput ?? KnownRobots.lastAddress.map(\.displayString) ?? "")
        _knownRobots = State(initialValue: knownRobots)
        _sweep = State(initialValue: sweep)
        _route = State(initialValue: route)
    }

    var body: some View {
        Group {
            if case let .connecting(.needsDaemonUpdate(_, requirement)) = session.phase {
                // Its own screen rather than a rail node: retrying is pointless here,
                // and everything the user can do is an update decision.
                NavigationStack {
                    DaemonUpdateScreen(session: session, requirement: requirement)
                }
            } else {
                segmentedBody
            }
        }
        .onAppear(perform: appeared)
        .sheet(isPresented: $showsOnboarding) {
            OnboardingFlow(onFinish: finishOnboarding) { showsOnboarding = false }
        }
        .onChange(of: browser.services) { _, services in
            knownRobots?.updateDiscovered(Set(services.compactMap(\.hardwareID)))
            sweep?.resolve(services)
        }
        .onChange(of: session.phase, initial: true) { _, phase in
            progress.observe(phase)
        }
        .onDisappear {
            guard !previewMode else { return }
            sweep?.stop()
            browser.stop()
            knownRobots?.stop()
        }
    }

    private var segmentedBody: some View {
        VStack(spacing: 0) {
            ConnectHeader(session: session, displayed: progress.displayed)
            ConnectRoutePicker(route: $route)
                .disabled(!session.phase.acceptsConnectionChoice)
                .padding(.horizontal, Space.lg)
                .padding(.bottom, Space.sm)
            form
        }
        // The header sits outside the `Form`, so it takes whatever backdrop it finds
        // rather than the grouped one the form paints for itself. `ConnectGate` sets
        // this too, but a screen cannot rely on its container for its own background:
        // without it here the reference images record a white strip above a grey page
        // — a difference from the shipping app that the snapshots would then defend.
        .groupedPageBackground()
    }

    private var form: some View {
        Form {
            switch route {
            case .network:
                NetworkRobotsSection(
                    session: session,
                    browser: browser,
                    entries: knownRobots?.entries ?? [],
                    connect: connectManually,
                    connectToService: connect(to:),
                    forget: { knownRobots?.forget($0) },
                    resolving: resolving
                )
                .disabled(!session.phase.acceptsConnectionChoice)
            case .account:
                // The one segment with no `disabled` on it, which is what its own
                // doc comment has always claimed. A robot reached through Hugging
                // Face is not on this Wi-Fi, so a sweep of this one says nothing
                // about whether it can be reached — and the sweep walks the phase
                // through `idle → handshaking → idle` every 10 s, so gating on it
                // made the only way to a remote robot go dead under a finger on a
                // beat the reader cannot see.
                YourReachiesSection(show: showRemoteRobots)
            case .manual:
                ManualAddressSection(input: $manualInput, connect: connectManually)
                    .disabled(!session.phase.acceptsConnectionChoice)
            }
            setUpSection
            privacySection
            errorSection
        }
        .formStyle(.grouped)
    }

    /// Outside the segments, for the same reason `setUpSection` is: a refused Local
    /// Network permission breaks *every* route, and the banner used to live inside
    /// `NetworkRobotsSection` where only one of the three could show it. Someone
    /// blocked from discovery reaches for the manual address next — the one place the
    /// explanation was invisible, while a typed address failed just as silently,
    /// because the permission gates plain HTTP to the LAN and not only Bonjour.
    ///
    /// The heartbeat question this screen's `AGENTS.md` insists on: nothing here keys
    /// off `session.phase` or `lastError`, so nothing mounts and unmounts on the 10 s
    /// sweep. `permissionLooksDenied` flips at most once in a browser's life.
    private var privacySection: some View {
        Section {
            if browser.permissionLooksDenied {
                Label(.reachy("Local Network permission denied"), systemImage: "exclamationmark.triangle")
                    .foregroundStyle(Tone.danger.style)
                PrivacySettingsButton(pane: .localNetwork)
            }
            if let showPermissions {
                Button(.reachy("Privacy permissions"), action: showPermissions)
            }
        } footer: {
            if browser.permissionLooksDenied {
                Text(.reachy("Without it this app cannot find the robot or reach it at a typed address."))
            }
        }
    }

    /// The last error, shown only once the sweep has stopped rewriting it.
    ///
    /// `beginAttempt` clears `lastError` and `failAttempt` sets it — for automatic
    /// attempts too, since the guard that keeps the phase on `.idle` comes after the
    /// assignment. So while the sweep is running this section mounts and unmounts
    /// every 10 s, which was the second half of the reported jitter and survived the
    /// stepper being taken out of the form.
    ///
    /// Suppressing it there loses nothing: a failure the reader triggered is already
    /// named on the rail's own detail line, and one from a background retry says
    /// `Could not connect to the server` about an address nobody chose, under a list
    /// that already reads "Searching…" with two paragraphs explaining it.
    @ViewBuilder
    private var errorSection: some View {
        if let error = session.lastError, !session.automaticConnectionAllowed {
            Section {
                Text(error)
                    .font(Typography.consoleLine)
                    .foregroundStyle(Tone.danger.style)
            }
        }
    }

    /// Its own section so the sweep cannot switch it off, and outside the segments
    /// so no choice of segment can hide it.
    private var setUpSection: some View {
        Section {
            if let awaitedHardwareID {
                Label(
                    .reachy(
                        // swiftlint:disable:next line_length
                        "Waiting for the robot you just set up (\(awaitedHardwareID)). If this phone is still on reachy-mini-ap, switch it back to your home Wi-Fi."
                    ),
                    systemImage: "clock.arrow.circlepath"
                )
                .font(Typography.status)
                .foregroundStyle(Tone.quiet.style)
            }
            Button(.reachy("Set up a new robot over Bluetooth")) {
                showsOnboarding = true
            }
        }
    }

    private func appeared() {
        guard !previewMode else { return }
        let robots = knownRobots ?? KnownRobotsModel()
        knownRobots = robots
        robots.start()
        browser.start()
        let sweep = sweep ?? CandidateSweep(session: session)
        self.sweep = sweep
        sweep.start()
        // Only the very first launch, and never as a gate: a robot already on the
        // network is found without any of this, and the button below reopens it.
        if KnownRobots.lastAddress == nil, !KnownRobots.hasCompletedOnboarding {
            showsOnboarding = true
        }
    }

    /// The robot reported where it landed over Bluetooth, which beats waiting for the
    /// sweep to stumble across it. The hardware id is what confirms the arrival, and
    /// `RobotSession` clears it on the handshake.
    private func finishOnboarding(_ outcome: OnboardingOutcome) {
        showsOnboarding = false
        awaitedHardwareID = outcome.hardwareID
        guard let address = outcome.address else { return }
        sweep?.expect(address)
    }

    private func connectManually(to address: RobotAddress) {
        sweep?.standDown()
        Task { await session.connect(to: address) }
    }

    private func connect(to service: RobotBrowser.DiscoveredService) {
        sweep?.standDown()
        resolving = service.id
        Task {
            defer { resolving = nil }
            guard let address = await BonjourResolver.resolve(service.endpoint) else { return }
            await session.connect(to: address)
        }
    }
}

extension RobotSession.ConnectionPhase {
    /// A connection choice may start only while no attempt or decision is active.
    /// The setup-over-Bluetooth section does not read this value and deliberately
    /// remains available while an automatic attempt is failing.
    var acceptsConnectionChoice: Bool {
        if case .idle = self {
            true
        } else {
            false
        }
    }
}

import Foundation
import Observation

/// This app's own Hugging Face session: what it holds, and how it got it.
///
/// Deliberately separate from a robot's account. Signing in here is what makes
/// "Your Reachies" possible at all — it is how central knows whose robots to
/// list — and linking a robot is a second, explicit act.
///
/// The browser is not here. Opening a URL and receiving the callback belongs to
/// the UI layer, which has `ASWebAuthenticationSession`; this owns the parts that
/// have to be right whether or not a browser is involved.
@MainActor
@Observable
public final class HFAccount {
    public enum State: Equatable, Sendable {
        case signedOut
        case signingIn
        case signedIn(username: String)
        /// The session lapsed and cannot be renewed silently. The username is kept
        /// so the prompt can name whose session it was.
        case needsReauth(username: String?)
        case failed(String)
    }

    public private(set) var state: State = .signedOut

    private let configuration: HFOAuthConfiguration
    private let store: any HFTokenStoring
    private let exchanger: any HFTokenExchanging
    private let now: @Sendable () -> Date
    private var token: HFToken?
    /// The PKCE pair and state of the sign-in currently in flight. Held here so a
    /// callback can be checked against what this app actually asked for.
    private var pending: (pkce: HFOAuth.PKCE, state: String)?

    public init(
        configuration: HFOAuthConfiguration = .reachyMini,
        store: any HFTokenStoring = InMemoryHFTokenStore(),
        exchanger: (any HFTokenExchanging)? = nil,
        now: @escaping @Sendable () -> Date = { Date() }
    ) {
        self.configuration = configuration
        self.store = store
        self.exchanger = exchanger ?? HFTokenExchanger(configuration: configuration)
        self.now = now
    }

    /// False until the OAuth app is registered on the Hub. The pasted-token path
    /// stays available either way, which is what makes this an honest question for
    /// a screen to ask rather than a dead button.
    public var canSignInWithBrowser: Bool {
        configuration.isConfigured
    }

    public var username: String? {
        switch state {
        case let .signedIn(username): username
        case let .needsReauth(username): username
        default: nil
        }
    }

    /// Reads whatever the last launch left behind. Cheap and offline — the token's
    /// own expiry is enough to decide, with no call to the Hub.
    public func restore() {
        token = try? store.load()
        guard let token else {
            state = .signedOut
            return
        }
        state = token.needsReauth(at: now())
            ? .needsReauth(username: token.username)
            : .signedIn(username: token.username ?? "")
    }

    /// The URL to open in the browser. Remembers the PKCE pair the callback will
    /// be checked against.
    public func beginSignIn() throws -> URL {
        guard configuration.isConfigured else { throw HFOAuthError.notConfigured }
        let pkce = HFOAuth.PKCE()
        let state = UUID().uuidString
        guard let url = HFOAuth.authorizationURL(configuration: configuration, pkce: pkce, state: state) else {
            throw HFOAuthError.notConfigured
        }
        pending = (pkce, state)
        self.state = .signingIn
        return url
    }

    /// Finishes what `beginSignIn()` started. Refuses a callback whose state this
    /// app did not issue, and never stores a token it could not attribute.
    public func completeSignIn(callback: URL) async {
        guard let pending else {
            state = .failed(HFOAuthError.stateMismatch.localizedDescription)
            return
        }
        self.pending = nil
        do {
            let code = try HFOAuth.code(in: callback, expectedState: pending.state)
            let issued = try await exchanger.exchange(code: code, verifier: pending.pkce.verifier)
            let username = try await exchanger.username(for: issued.accessToken)
            try keep(issued.named(username))
            state = .signedIn(username: username)
        } catch {
            state = .failed(Self.describe(error))
        }
    }

    /// The personal-access-token path: the way in without a registered OAuth app,
    /// and the way in for anyone who would rather not use a browser at all.
    public func signIn(pastedToken: String) async {
        let trimmed = pastedToken.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmed.isEmpty else {
            state = .failed(HFOAuthError.invalidToken.localizedDescription)
            return
        }
        state = .signingIn
        do {
            // Validated against the Hub rather than pattern-matched: a token that
            // looks right and is not would fail later, somewhere less explicable.
            let username = try await exchanger.username(for: trimmed)
            try keep(HFToken(accessToken: trimmed, username: username))
            state = .signedIn(username: username)
        } catch {
            state = .failed(Self.describe(error))
        }
    }

    /// Forgets this app's token. A robot that was linked keeps its own copy — that
    /// is a separate act to undo, and doing it silently here would leave the user
    /// believing a robot went offline when it did not.
    public func signOut() {
        try? store.clear()
        token = nil
        pending = nil
        state = .signedOut
    }

    /// The token to put in an `Authorization` header, renewed first if it is due.
    ///
    /// Renewal happens here rather than on a timer because this is the only moment
    /// that knows the token is about to be used.
    public func currentToken() async -> String? {
        guard let token else { return nil }
        guard token.isExpired(at: now()) else { return token.accessToken }
        do {
            let renewed = try await exchanger.refreshing(token)
            try keep(renewed)
            state = .signedIn(username: renewed.username ?? "")
            return renewed.accessToken
        } catch {
            state = .needsReauth(username: token.username)
            return nil
        }
    }

    private func keep(_ token: HFToken) throws {
        try store.save(token)
        self.token = token
    }

    private static func describe(_ error: any Error) -> String {
        (error as? LocalizedError)?.errorDescription ?? error.localizedDescription
    }
}

